618	async function cmdCancelBooking(args: string[]): Promise<void> {
619	  const {values, positionals} = parseFlags(args, []);
620	  if (values.size > 0) {
621	    throw new UsageError(`cancel-booking 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`);
622	  }
623	  if (positionals.length !== 1) throw new UsageError('用法: cancel-booking <预约标识>');
624	  const id = positionals[0];
625	
626	  const file = activeDataFile;
627	  const store = await loadStore(file);
628	  const booking = store.bookings.find((b) => b.id === id);
629	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
630	  if (booking.status === 'cancelled') {
631	    // 幂等：再次取消成功且不做任何改动
632	    console.log(`预约 ${id} 已是取消状态，未做改动。`);
633	    return;
634	  }
635	  booking.status = 'cancelled'; // 已取消记录保留，但不再参与冲突检查
636	  await saveStore(file, store);
