394	function formatResourceIds(store: Store, ids: string[]): string {
395	  return ids
396	    .map((id) => {
397	      const r = store.resources.find((x) => x.id === id);
398	      return r ? `${id}（${r.name}）` : id;
399	    })
400	    .join('、');
401	}
