403	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
404	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
405	  const problems: string[] = [];
406	  const seen = new Set<string>();
407	  const dupes: string[] = [];
408	  for (const id of rawIds) {
409	    if (seen.has(id)) {
410	      if (!dupes.includes(id)) dupes.push(id);
411	    }
412	    seen.add(id);
413	  }
414	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
415	
416	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
417	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
418	
419	  if (problems.length > 0) throw new BizError(problems.join('\n'));
420	  return [...seen].sort();
421	}
422	
423	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
424	  return mergeIntervals(
425	    r.open.map(
426	      ([s, e]) =>
427	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
428	    ),
429	  );
430	}
431	
432	// 找出开放区间不能完整覆盖 [startMin, endMin) 的资源
433	function findCoverageGaps(
434	  store: Store,
435	  ids: string[],
436	  startMin: number,
437	  endMin: number,
438	): Array<{id: string; r: ResourceRec}> {
439	  return ids
440	    .map((id) => ({id, r: store.resources.find((x) => x.id === id)!}))
441	    .filter(({r}) => !isFullyCovered(openSegmentsOf(r), startMin, endMin));
442	}
443	
444	// 校验每个资源的开放区间都能完整覆盖 [startMin, endMin)
445	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
446	  const failing = findCoverageGaps(store, ids, startMin, endMin);
447	  if (failing.length > 0) {
448	    throw new BizError(
449	      '开放时间不足，以下资源的开放区间不能完整覆盖预约区间：\n' +
450	        failing.map(({id, r}) => `- ${id}（${r.name}）`).join('\n'),
451	    );
452	  }
453	}
