460	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
461	function findConflicts(
462	  store: Store,
463	  ids: string[],
464	  startMin: number,
465	  endMin: number,
466	  excludeBookingId?: string,
467	): Conflict[] {
468	  const wanted = new Set(ids);
469	  const conflicts: Conflict[] = [];
470	  for (const b of store.bookings) {
471	    if (b.status !== 'active') continue;
472	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
473	    const bStart = parseDateTime(b.start, '预约开始时间');
474	    const bEnd = parseDateTime(b.end, '预约结束时间');
475	    const overlap = bStart < endMin && startMin < bEnd;
476	    if (!overlap) continue;
477	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
478	    if (shared.length > 0) conflicts.push({booking: b, shared});
479	  }
480	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
481	  return conflicts;
482	}
